import { Component, Prop, h, Host, Element, ComponentInterface } from '@stencil/core';
import classnames from 'classnames';
import { AvatarPropShape, AvatarSize } from './avatar';
import { Slot, type Slots } from '@src/framework/decorators';
import { KsTextVariant } from '@src/components';

function getTextVariant(size: AvatarSize): KsTextVariant {
  switch (size) {
    case 'xs':
    case 'sm':
      return 'labelSm';
    case 'lg':
      return 'labelLg';
    case 'md':
    default:
      return 'labelMd';
  }
}

const prefix = 'avatar';

/**
 * @slot default - Content rendered inside the avatar, such as initials or custom fallback content.
 * @slot overlap - Used to place elements on top of the avatar, often for badges or status indicators. only takes effect when size is lg
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-avatar',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsAvatar implements ComponentInterface {
  @Element() el!: HTMLKsAvatarElement;

  /** If true, the avatar is visually styled as disabled and non-interactive. */
  @Prop() disabled = false;

  /**
   * The shape of the avatar component. Can be one of the following values:
   * - `"circle"`: The avatar is displayed with a circular shape.
   * - `"square"`: The avatar is displayed with a square shape.
   */
  @Prop() shape: AvatarPropShape = 'circle';
  /** The size of the avatar component. Can be one of the following values: `xs`, `"sm"`, `"md"`, or `"lg"`. */
  @Prop() size: AvatarSize = 'md';
  /** The source URL of the image for the avatar component. If not empty, the avatar will display an image. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() src: string;
  /** The text to display as a tooltip for the avatar image (when `src` is used). This is passed to the `title` attribute of the `<img>` tag. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() alt: string;
  /** The name portion of the text label */
  @Prop() name = '';
  /** The descriptive text displayed below the name in the label (if `showLabel` is true). */
  @Prop() description = '';

  /** The components overlap in the lower right corner of the avatar. only takes effect when size is lg */
  @Slot({ slotname: 'overlap' }) overlapSlot?: Slots;

  private renderAvatar() {
    const classes = classnames([
      `${prefix}`,
      `${prefix}--${this.shape}`,
      `${prefix}--${this.size}`,
      { [`${prefix}--image`]: !!this.src },
      { [`${prefix}--disabled`]: this.disabled },
    ]);
    const style = {
      background: this.src
        ? this.disabled
          ? `url(${this.src}) lightgray 50% / cover no-repeat`
          : `url(${this.src}) lightgray 50% / cover no-repeat`
        : '',
    };
    return (
      <div part="base" style={style} class={classes}>
        <slot></slot>
        {this.overlapSlot && this.size === 'lg' && !this.disabled && (
          <div class={`${prefix}__overlap ${prefix}__overlap--${this.shape}`}>
            <slot name="overlap"></slot>
          </div>
        )}
      </div>
    );
  }

  render() {
    const showLabel = this.name || this.description;
    // TODO here: AntD supports adaptive font-size
    return (
      <Host
        class={{
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          [`${prefix}-host-group`]: (this.el.parentElement as any)?.['ks-name'] === 'ks-avatar-group',
          KsAvatar: true,
        }}
      >
        <div class={`${prefix}-container`}>
          {this.renderAvatar()}
          {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (this.el.parentElement as any)?.['ks-name'] !== 'ks-avatar-group' && showLabel && (
              <div class={`${prefix}-label`}>
                <ks-text variant={getTextVariant(this.size)}>{this.name}</ks-text>
                <ks-text variant="labelSm" color="neutral">
                  {this.description}
                </ks-text>
              </div>
            )
          }
        </div>
      </Host>
    );
  }
}
